function editRows(section,keys,s){
 const map=section==='control'?state.controlEdits||{}:section==='scenario'?state.scenarioEdits?.[s.id]||{}:state.fmEdits?.[s.model]||{};
 const allFm=workingFm(s,FM_DEFAULTS,state.fmEdits?.[s.model]||{});
 return `<div class="setting-grid">${keys.filter(k=>section==='control'?DATA.controls[k]:section==='scenario'?Object.hasOwn(s.assumptions,k):Object.hasOwn(allFm,k)).map(k=>{
  const readonly=section==='control'?READONLY_CONTROLS.has(k):section==='scenario'?READONLY_SCENARIO.has(k):FM_DERIVED.includes(k);
  const base=inputBase(section,k,s,DATA.controls,FM_DEFAULTS);
  const curr=readonly&&section==='fm'?allFm[k]:effective(base,map,k);
  const fraction=isFraction(section,k),unit=section==='control'?DATA.controls[k]?.unit:section==='scenario'?SCENARIO_UNITS[k]||(fraction?'%':k.toLowerCase().includes('cost')||k.toLowerCase().includes('fee')?'$ or share':'value'):k.includes('pay')||k.includes('maintenance')||k.includes('security')||k.includes('staff')||k.includes('scope')||k.includes('fee')||k.includes('safety')||k.includes('spares')||k.includes('BMS')||k.includes('fuel')?'$/year':k.includes('posts')||k.includes('FTE')?'staff':'hours/year';
  const cfg=EDITORS[k];const recordedOnly=RECORDED_ONLY[section]?.has(k);let control='';
  if(readonly)control=`<div class="readonly-value">${esc(fraction?fmtNum(curr*100)+'%':typeof curr==='number'?fmtNum(curr):curr)}</div>`;
  else if(cfg?.choices)control=`<select class="select settings-input" data-edit-input="${section}" data-key="${esc(k)}">${cfg.choices.map(([v,l])=>`<option value="${v}" ${Number(curr)===v?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
  else if(cfg?.type==='date'){
   const iso=new Date(Date.UTC(1899,11,30)+Number(curr)*86400000).toISOString().slice(0,10);
   control=`<input class="input-edit settings-input" type="date" data-edit-input="${section}" data-key="${esc(k)}" value="${iso}"/>`;
  }else control=`<input class="input-edit settings-input" type="text" inputmode="decimal" data-edit-input="${section}" data-key="${esc(k)}" value="${esc(fmtInput(curr,section,k))}"/>`;
  return `<label class="setting-tile ${Object.hasOwn(map,k)?'edited':''} ${readonly?'readonly':''}"><div class="setting-top"><span class="setting-name">${esc(k)}</span>${helpIcon(section,k)}${Object.hasOwn(map,k)?'<span class="edit-dot">EDITED</span>':recordedOnly?'<span class="record-dot">REFERENCE ONLY</span>':''}</div>${control}<div class="setting-bottom"><span>${esc(fraction?'%':unit||'value')}</span><span>${readonly?'Calculated / fixed':recordedOnly?'Saved, not in IRR calculation':`Base: ${esc(fraction?fmtNum(base*100)+'%':typeof base==='number'?fmtNum(base):base)}`}</span></div></label>`;}).join('')}</div>`;
}
